INSERT INTO ads_strategy (
    strategy_id, tenant_id, strategy_code, strategy_name, strategy_type, target_campaign_id,
    conditions_json, actions_json, pms_generated, schedule_expression, status,
    last_executed_at, created_at, updated_at
) VALUES (
    #{strategyId}, #{tenantId}, #{strategyCode}, #{strategyName}, #{strategyType}, #{targetCampaignId},
    #{conditionsJson}, #{actionsJson}, #{pmsGenerated}, #{scheduleExpression}, #{status},
    #{lastExecutedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT strategy_id, tenant_id, strategy_code, strategy_name, strategy_type, target_campaign_id,
       conditions_json, actions_json, pms_generated, schedule_expression, status,
       last_executed_at, created_at, updated_at
FROM ads_strategy
WHERE tenant_id = #{tenantId}
  AND strategy_id = #{strategyId}

SELECT strategy_id, tenant_id, strategy_code, strategy_name, strategy_type, target_campaign_id, conditions_json, actions_json, pms_generated, schedule_expression, status, last_executed_at, created_at, updated_at FROM ads_strategy WHERE tenant_id = #{tenantId}
AND strategy_type = #{strategyType}
ORDER BY created_at DESC

mapper.delete:
DELETE FROM ads_strategy
WHERE tenant_id = #{tenantId}
  AND strategy_id = #{strategyId}

