INSERT INTO ads_search_term_analysis (
    analysis_id, tenant_id, campaign_id, search_term, impressions, clicks, ctr, acos, orders,
    performance, suggested_keywords, analyzed_at
) VALUES (
    #{analysisId}, #{tenantId}, #{campaignId}, #{searchTerm}, #{impressions}, #{clicks},
    #{ctr}, #{acos}, #{orders}, #{performance}, #{suggestedKeywords}, #{analyzedAt}
)

mapper.select:
SELECT analysis_id, tenant_id, campaign_id, search_term, impressions, clicks, ctr, acos, orders,
       performance, suggested_keywords, analyzed_at
FROM ads_search_term_analysis
WHERE tenant_id = #{tenantId}
  AND campaign_id = #{campaignId}
ORDER BY analyzed_at DESC

